import React from 'react';
import Button from '@mui/lab/LoadingButton';

interface IAppButton {
  variant?: "text" | "contained" | "outlined";
  color?: 'inherit' | 'primary' | 'secondary' | 'success' | 'error' | 'info' | 'warning';
  size?: "small" | "medium" | "large";
  isDisabled?: boolean;
  isLoading?: boolean;
  text: string;
  startIcon?: React.ReactNode;
  endIcon?: React.ReactNode;
  onClick?: () => void;
}

export const AppButton: React.FC<IAppButton> = ({
  variant = "text",
  color = "inherit",
  size = "medium",
  text,
  isDisabled,
  isLoading = false,
  startIcon,
  endIcon,
  onClick,
  ...props
}) => {
  return (
      <Button
        loading={isLoading}
        disabled={isDisabled}
        variant={variant}
        color={color}
        size={size}
        startIcon={startIcon}
        endIcon={endIcon}
        onClick={onClick}
        {...props}
      >
        {text}
      </Button>
  );
}